-- Metadata-only company catalog. Sources are fetched only after at least one
-- user follows them. Every board below was verified against its public ATS API
-- on 2026-08-18.
ON CONFLICT (provider, external_key) DO UPDATE SET
  company_name = EXCLUDED.company_name,
  career_url = EXCLUDED.career_url,
  config = EXCLUDED.config,
  enabled = true;

NOTIFY pgrst, 'reload schema';
